export function mountAtlasRendering(api){const {THREE:T}=api;let mode='studio';const host=document.createElement('div');host.className='atlasRenderControls';host.innerHTML='<span>ILUMINACIÓN DEL MODELO</span><button data-render="studio" aria-pressed="true">Estudio</button><button data-render="inspection" aria-pressed="false">Inspección</button><button data-render="contrast" aria-pressed="false">Contraste</button><small>Cuerpos aproximados · coordenadas y redes del modelo</small>';document.querySelector('.viewer').append(host);
 function apply(next){mode=next;const {scene,renderer}=api.scene();host.querySelectorAll('[data-render]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.render===mode)));if(!scene||!renderer)return;scene.background=new T.Color(mode==='inspection'?'#cbd5dc':mode==='contrast'?'#020609':'#111c28');renderer.toneMapping=T.NeutralToneMapping;renderer.toneMappingExposure=mode==='inspection'?1.05:mode==='contrast'?.95:1.0;scene.environmentIntensity=mode==='inspection'?.85:.65;const key=scene.getObjectByName('studioKey');if(key)key.intensity=mode==='contrast'?3.1:mode==='inspection'?2.5:2.2;let rim=scene.getObjectByName('atlasRim');if(!rim){rim=new T.DirectionalLight('#b7d7ff',1.4);rim.name='atlasRim';rim.position.set(85,65,90);scene.add(rim);}rim.intensity=mode==='contrast'?2.2:mode==='studio'?1.4:.65;}
 host.querySelectorAll('[data-render]').forEach(b=>b.onclick=()=>apply(b.dataset.render));apply(mode);return {apply};}
